// Generates the browser globals from the JSON sources in data/source/.
//   node scripts/build-runtime.mjs          write the generated files
//   node scripts/build-runtime.mjs --check  fail if a generated file is out of date
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const targets = [
  { source: 'data/source/chemicals.json', output: 'chatbot/msds/msds-db.js', global: 'chemicalMsdsDb' },
  { source: 'data/source/equipment.json', output: 'equipment-data.js', global: 'LAB_EQUIPMENT_CATALOG' },
];

// Fields kept in the JSON source only. Pages do not read them yet, so they stay out of the shipped bundle.
const sourceOnly = new Set(['wasteStream', 'wasteStreamReview', 'incompatibleWith', 'avoidConditions', 'handlingRestrictions']);

const render = ({ source, global }) => {
  const records = JSON.parse(fs.readFileSync(path.join(root, source), 'utf8'))
    .map(record => Object.fromEntries(Object.entries(record).filter(([key]) => !sourceOnly.has(key))));
  return `/* Generated by scripts/build-runtime.mjs from ${source}. Do not edit by hand. */\nwindow.${global} = ${JSON.stringify(records)};\n`;
};

const check = process.argv.includes('--check');
let stale = 0;

for (const target of targets) {
  const expected = render(target);
  const outputPath = path.join(root, target.output);
  const current = fs.existsSync(outputPath) ? fs.readFileSync(outputPath, 'utf8') : null;
  if (current === expected) continue;
  if (check) {
    console.error(`stale  ${target.output} (run: npm run data:runtime)`);
    stale += 1;
  } else {
    fs.writeFileSync(outputPath, expected);
    console.log(`wrote  ${target.output}`);
  }
}

if (check) {
  if (stale) process.exit(1);
  console.log('runtime data files are up to date');
}
